/**
 * THE PARITY PROOF for sealed boards and cards (`docs/security/private-repos.md` §4.6): every
 * `sealed_board__*` vector in `forge-contracts/vectors/` (generated by
 * `tools/private-repos-vectors/boards.py`, an independent reference), run against `./board`.
 * forge-core has no reader yet; `dg board` implements the same against these files.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

import { openBoardDoc, parseBoardTlv, sealBoardDoc, type BoardBind, type BoardFields, type BoardOpenResult, type CardFields } from './board'
import { bytesToHex, hexToBytes } from './bytes'
import type { OpenContext } from './doc'
import { IdSet, privateId } from './ids'
import { EpochKeys, type EpochKeyring } from './keys'
import { sealBoardDocWithNonce } from './testing'
import { MalformedError } from './tlv'

type Json = null | boolean | number | string | Json[] | { [k: string]: Json }
type Obj = { readonly [k: string]: Json }

interface Vector {
  readonly name: string
  readonly case: string
  readonly input: Obj
  readonly expected: Json
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => f.startsWith('sealed_board__') && f.endsWith('.json'))
  .sort()

const obj = (j: Json | undefined): Obj => j as Obj
const hex = (j: Json | undefined): Uint8Array => hexToBytes(j as string)

function bindOf(d: Obj): BoardBind {
  return d['type'] === 'board' ? { type: 'board', key: d['key'] as number } : { type: 'card', board: d['board'] as number, item: hex(d['item']) }
}

async function contextOf(repoId: Uint8Array, c: Obj): Promise<OpenContext> {
  const keys = new Map<number, EpochKeys>()
  for (const [e, k] of Object.entries(obj(c['keys']))) keys.set(Number(e), await EpochKeys.import(repoId, Number(e), hex(k)))
  const members = (c['members'] ?? []) as string[]
  const burned = (c['burned'] ?? []) as number[]
  return {
    keys: keys as EpochKeyring,
    anchors: new Map(Object.entries(obj(c['anchors'])).map(([e, a]) => [Number(e), { id: privateId(obj(a)['id'] as string), height: obj(a)['height'] as number, statedHeight: obj(a)['height'] as number }])),
    members: new IdSet(members.map((m) => privateId(m))),
    burned: new Set(burned),
  }
}

function openJson(r: BoardOpenResult): Json {
  if (r.status === 'readable') return { status: 'readable', fields: { ...r.fields } as Obj }
  return r.status === 'unreadable' ? { status: 'unreadable', reason: r.reason } : { status: 'malformed' }
}

async function run(v: Vector): Promise<Json> {
  const inp = v.input
  const repoId = hex(inp['repoId'])
  if (inp['op'] === 'seal') {
    const keys = await EpochKeys.import(repoId, inp['epoch'] as number, hex(inp['key']))
    const bind = bindOf(obj(inp['doc']))
    const fields = obj(inp['fields']) as unknown as BoardFields | CardFields
    try {
      const sealed = await sealBoardDocWithNonce(keys, hex(inp['ownerId']), bind, fields, hex(inp['nonce']))
      // what the writer seals is what a reader accepts
      expect(parseBoardTlv(bind.type, sealed.tlv)).toEqual(fields)
      return { ad: bytesToHex(sealed.ad), tlv: bytesToHex(sealed.tlv), enc: bytesToHex(sealed.enc) }
    } catch (e) {
      if (e instanceof MalformedError) return { error: 'malformed' }
      throw e
    }
  }
  const d = obj(inp['doc'])
  const ctx = await contextOf(repoId, obj(inp['context']))
  return openJson(
    await openBoardDoc(ctx, {
      bind: bindOf(d),
      ownerId: hex(d['ownerId']),
      epoch: d['epoch'] as number,
      ...(d['enc'] !== undefined ? { enc: hex(d['enc']) } : {}),
      hasPlaintextContent: d['plaintext'] === true,
    }),
  )
}

describe('sealed_board vectors (private-repos.md §4.6)', () => {
  it('loads both ops', () => {
    const ops = FILES.map((f) => (JSON.parse(readFileSync(resolve(VECTORS_DIR, f), 'utf8')) as Vector).input['op'])
    expect(ops.filter((o) => o === 'seal').length).toBeGreaterThanOrEqual(15)
    expect(ops.filter((o) => o === 'open').length).toBeGreaterThanOrEqual(20)
  })

  for (const file of FILES) {
    const v = JSON.parse(readFileSync(resolve(VECTORS_DIR, file), 'utf8')) as Vector
    it(v.name, async () => {
      expect(v.case).toBe('sealed_board')
      expect(await run(v)).toEqual(v.expected)
    })
  }
})

describe('sealBoardDoc (hedged nonce)', () => {
  it('round-trips a board and a card, and never seals the same bytes twice', async () => {
    const repoId = new Uint8Array(32).fill(0x11)
    const owner = new Uint8Array(32).fill(0x22)
    const keys = await EpochKeys.import(repoId, 3, new Uint8Array(32).fill(5))
    const ctx: OpenContext = { keys: new Map([[3, keys]]), anchors: new Map([[3, { id: new Uint8Array(32), height: 1, statedHeight: 1 }]]), members: new IdSet([]) }
    const board = { name: 'Roadmap', spec: '{"v":1,"columns":[{"id":1,"name":"Todo"}]}' }
    const a = await sealBoardDoc(keys, owner, { type: 'board', key: 9 }, board)
    const b = await sealBoardDoc(keys, owner, { type: 'board', key: 9 }, board)
    expect(bytesToHex(a)).not.toBe(bytesToHex(b))
    expect(await openBoardDoc(ctx, { bind: { type: 'board', key: 9 }, ownerId: owner, epoch: 3, enc: a, hasPlaintextContent: false })).toEqual({ status: 'readable', fields: board })
    const item = new Uint8Array(32).fill(0x44)
    const card = { col: 1, rank: 'Vx', f: '{"1":2}' }
    const c = await sealBoardDoc(keys, owner, { type: 'card', board: 9, item }, card)
    expect(await openBoardDoc(ctx, { bind: { type: 'card', board: 9, item }, ownerId: owner, epoch: 3, enc: c, hasPlaintextContent: false })).toEqual({ status: 'readable', fields: card })
  })
})
